export default {
    meta: {
        type: "problem",
        docs: {
            description: "require every spec.md / ADR to declare a parseable lifecycle status that matches its test-link coverage: no links -> Draft, some -> In Progress, all -> Shipped. Skips rejected/retired docs and docs with no testable statements.",
        },
        schema: [
            {
                type: "object",
                properties: { roots: DOC_ROOTS_SCHEMA },
                additionalProperties: false,
            },
        ],
        messages: {
            untagged: "This {{corpus}} declares no status the parsers can read, so its coverage cannot be checked and no status can be rendered for it. {{requirement}}",
            statusMismatch: 'Status "{{actual}}" does not match this {{corpus}}\'s test-link coverage — {{linked}} of {{testable}} testable statements carry a ([validated by](test.ts#Lline)) link. Either set the status to "{{expected}}", or link the remaining statements to the tests that validate them.',
        },
    },
    create(context) {
        const kind = docKind(context.filename, context.options[0]?.roots);
        if (!kind) {
